import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import QRCode from 'react-qr-code';
import { verifyPayment, clearCart } from '../services/api';

const UPIQRCode = ({ amount, orderId, onPaymentComplete, onClose, cartCount }) => {
  const navigate = useNavigate();
  const [upiId, setUpiId] = useState('amrutanshu20003-16@oksbi'); // Your UPI ID
  const [qrValue, setQrValue] = useState('');
  const [paymentStatus, setPaymentStatus] = useState('pending');
  const [countdown, setCountdown] = useState(300); // 5 minutes countdown
  const [showTimer, setShowTimer] = useState(true);
  const [verificationAttempts, setVerificationAttempts] = useState(0);
  const [autoVerification, setAutoVerification] = useState(true);
  const verificationInterval = useRef(null);

  useEffect(() => {
    generateUPIString();
  }, [amount, orderId, upiId]);

  useEffect(() => {
    if (showTimer && countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else if (countdown === 0) {
      setPaymentStatus('expired');
      stopAutoVerification();
    }
  }, [countdown, showTimer]);

  useEffect(() => {
    if (autoVerification && paymentStatus === 'pending' && orderId) {
      startAutoVerification();
    }
    return () => stopAutoVerification();
  }, [autoVerification, paymentStatus, orderId]);

  // Prevent body scroll when modal is open
  useEffect(() => {
    // Disable scroll
    document.body.style.overflow = 'hidden';
    document.body.style.position = 'fixed';
    document.body.style.width = '100%';

    return () => {
      // Enable scroll when modal closes
      document.body.style.overflow = '';
      document.body.style.position = '';
      document.body.style.width = '';
    };
  }, []);

  const generateUPIString = () => {
    // UPI URI format: upi://pay?pa=UPI_ID&pn=Merchant_Name&am=Amount&cu=Currency&tn=Transaction_Note
    const upiString = `upi://pay?pa=${upiId}&pn=MilkMitra&am=${amount}&cu=INR&tn=Order_${orderId}`;
    setQrValue(upiString);
  };

  const handleUpiIdChange = (e) => {
    setUpiId(e.target.value);
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const startAutoVerification = () => {
    stopAutoVerification();
    verificationInterval.current = setInterval(async () => {
      try {
        const res = await verifyPayment(orderId);
        setVerificationAttempts(prev => prev + 1);

        if (res.data.status === 'completed') {
          setPaymentStatus('completed');
          stopAutoVerification();

          // Show success notification
          showPaymentSuccessNotification(res.data);

          if (onPaymentComplete) {
            handlePaymentComplete();
          }
        }

        // Stop verification after 30 attempts (5 minutes)
        if (verificationAttempts >= 30) {
          stopAutoVerification();
        }
      } catch (error) {
        console.error('Payment verification error:', error);
      }
    }, 5000); // Check every 5 seconds for faster detection
  };

  const showPaymentSuccessNotification = (paymentData) => {
    // Create a custom notification
    const notification = document.createElement('div');
    notification.className = 'fixed top-4 right-4 bg-green-500 text-white px-6 py-4 rounded-lg shadow-lg z-50 animate-pulse';
    notification.innerHTML = `
      <div class="flex items-center space-x-3">
        <div class="text-2xl">✅</div>
        <div>
          <div class="font-bold">Payment Successful!</div>
          <div class="text-sm">₹${paymentData.amount} received</div>
          <div class="text-xs">Transaction ID: ${paymentData.transactionId || 'N/A'}</div>
        </div>
      </div>
    `;

    document.body.appendChild(notification);

    // Auto remove after 5 seconds
    setTimeout(() => {
      if (notification.parentNode) {
        notification.parentNode.removeChild(notification);
      }
    }, 5000);

    // Play success sound (if available)
    try {
      const audio = new Audio('data:audio/wav;base64,UklGRnoGAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQoGAACBhYqFbF1fdJivrJBhNjVgodDbq2EcBj+a2/LDciUFLIHO8tiJNwgZaLvt559NEAxQp+PwtmMcBjiR1/LMeSwFJHfH8N2QQAoUXrTp66hVFApGn+DyvmwhBTGH0fPTgjMGHm7A7+OZURE');
      audio.volume = 0.3;
      audio.play().catch(() => {});
    } catch (e) {
      // Ignore audio errors
    }
  };

  const stopAutoVerification = () => {
    if (verificationInterval.current) {
      clearInterval(verificationInterval.current);
      verificationInterval.current = null;
    }
  };

  const handlePaymentConfirmation = () => {
    setPaymentStatus('verifying');
    // Manual verification fallback
    setTimeout(() => {
      setPaymentStatus('completed');
      if (onPaymentComplete) {
        onPaymentComplete();
      }
    }, 2000);
  };

  const handlePaymentComplete = async () => {
    try {
      await clearCart();
      if (cartCount) cartCount(0);
      // For online payments, redirect to verification page
      navigate(`/order-verification/${orderId}`, { 
        state: { 
          orderId: orderId,
          paymentMethod: 'online'
        } 
      });
    } catch (error) {
      console.error('Error completing payment:', error);
    }
  };

  const handleRetry = () => {
    setCountdown(300);
    setPaymentStatus('pending');
    setShowTimer(true);
    setVerificationAttempts(0);
    setAutoVerification(true);
  };

  if (paymentStatus === 'completed') {
    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
        <div className="bg-white rounded-lg p-8 max-w-md w-full mx-4">
          <div className="text-center">
            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path>
              </svg>
            </div>
            <h3 className="text-xl font-semibold text-gray-800 mb-2">Payment Successful!</h3>
            <p className="text-gray-600 mb-6">Your payment of ₹{amount} has been received successfully.</p>
            <button
              onClick={onClose}
              className="btn btn-primary w-full"
            >
              Continue
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 overflow-hidden">
      <div className="bg-white rounded-lg p-4 max-w-md w-full mx-auto max-h-[95vh] flex flex-col overflow-hidden">
        <div className="flex justify-between items-center mb-3 flex-shrink-0">
          <h3 className="text-lg font-semibold text-gray-800">UPI Payment</h3>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 p-1"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path>
            </svg>
          </button>
        </div>

        <div className="text-center mb-4 flex-shrink-0">
          <div className="text-2xl font-bold text-primary-600 mb-1">₹{amount}</div>
          <div className="text-xs text-gray-600">Order ID: {orderId}</div>
        </div>

        {/* Main Content - Side by Side Layout */}
        <div className="flex gap-4 mb-4 flex-1 overflow-hidden">
          {/* Left Side - QR Code */}
          <div className="flex-1 flex flex-col items-center justify-center">
            <div className="bg-white p-2 rounded-lg border-2 border-gray-200 w-full">
              <div className="flex justify-center mb-2">
                {qrValue && (
                  <QRCode
                    value={qrValue}
                    size={120}
                    level="H"
                    bgColor="#FFFFFF"
                    fgColor="#000000"
                  />
                )}
              </div>
              <div className="text-center text-xs text-gray-600">
                Scan with UPI app
              </div>
            </div>
          </div>

          {/* Right Side - Features */}
          <div className="flex-1 flex flex-col space-y-3 overflow-hidden">
            {/* Timer */}
            {showTimer && paymentStatus === 'pending' && (
              <div className="text-center">
                <div className="text-xs text-gray-600 mb-1">QR expires in</div>
                <div className={`text-lg font-mono font-bold ${countdown < 60 ? 'text-red-600' : 'text-gray-800'}`}>
                  {formatTime(countdown)}
                </div>
              </div>
            )}

            {/* Auto Verification Status */}
            {autoVerification && paymentStatus === 'pending' && (
              <div className="text-center">
                <div className="text-xs text-blue-600 font-medium mb-1">
                  🔄 Auto-checking...
                </div>
                <div className="text-xs text-gray-500">
                  Check: {verificationAttempts + 1}/30
                </div>
              </div>
            )}

            {/* Payment Status */}
            {paymentStatus === 'expired' && (
              <div className="text-center">
                <div className="text-sm text-red-600 font-semibold mb-2">QR Expired</div>
                <button
                  onClick={handleRetry}
                  className="btn btn-secondary text-sm py-1 px-3"
                >
                  New QR
                </button>
              </div>
            )}

            {paymentStatus === 'verifying' && (
              <div className="text-center">
                <div className="text-sm text-blue-600 font-semibold mb-2">Verifying...</div>
                <div className="spinner mx-auto w-4 h-4"></div>
              </div>
            )}

            {/* UPI ID Input */}
            <div className="flex-shrink-0">
              <label className="block text-xs font-medium text-gray-700 mb-1">
                Or pay to UPI ID:
              </label>
              <div className="flex gap-1">
                <input
                  type="text"
                  value={upiId}
                  onChange={handleUpiIdChange}
                  className="input flex-1 text-xs py-1 px-2"
                  placeholder="Enter UPI ID"
                />
                <button
                  onClick={() => navigator.clipboard.writeText(upiId)}
                  className="btn btn-secondary text-xs py-1 px-2"
                >
                  Copy
                </button>
              </div>
            </div>

            {/* Payment Instructions */}
            <div className="bg-gray-50 rounded-lg p-2 flex-shrink-0">
              <h4 className="font-semibold text-gray-800 mb-1 text-xs">How to Pay:</h4>
              <ol className="text-xs text-gray-600 space-y-0.5">
                <li>1. Open UPI app</li>
                <li>2. Scan QR or enter ID</li>
                <li>3. Enter amount: ₹{amount}</li>
                <li>4. Complete payment</li>
                <li>5. Auto-verification</li>
              </ol>
            </div>
          </div>
        </div>

        {/* Warning Message */}
        {paymentStatus === 'pending' && (
          <div className="bg-red-50 border-2 border-red-200 rounded-lg p-3 flex-shrink-0">
            <div className="flex items-center space-x-2">
              <div className="text-red-600 text-xl">⚠️</div>
              <div>
                <div className="font-semibold text-red-800 text-sm">Important Warning</div>
                <div className="text-red-700 text-xs">DO NOT CLOSE this window or go back until payment is completed</div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default UPIQRCode;
